223	<script>
224	  import { INTERVAL_MS, MAX_LINES, onLogLine } from '../lib/motion/consoleLog'
225	  import { metricsAt } from '../lib/motion/math'
226	  import { prefersReducedMotion } from '../lib/motion/reduced'
227	
228	  const log = document.querySelector<HTMLElement>('[data-log]')
229	  const template = log?.lastElementChild
230	  const figures = document.querySelectorAll<HTMLElement>('[data-metric]')
231	
232	  // With `reduce` the six server-rendered lines are the whole console: no cycle drives
233	  // the clock, so the time cells honestly stay empty (spec 06 §8).
234	  if (log && template && !prefersReducedMotion()) {
235	    /** Local `hh:mm:ss`. Never rendered on the server: a static build would freeze it. */
236	    const clock = (at: number) => new Date(at).toTimeString().slice(0, 8)
237	
238	    // Backdate the six lines already on screen, so they read as a log that has been
239	    // running rather than six events that happened in the same second.
240	    const first = Date.now() - (MAX_LINES - 1) * INTERVAL_MS
241	    Array.from(log.children).forEach((line, index) => {
242	      const time = line.firstElementChild
243	      if (time) time.textContent = clock(first + index * INTERVAL_MS)
244	    })
245	
246	    let tick = MAX_LINES
247	    onLogLine(({ key, value }) => {
248	      tick++
249	
250	      // Cloning the last line keeps the row markup in exactly one place, and a fresh
251	      // node is what replays the `rise` entry animation.
252	      const line = template.cloneNode(true) as HTMLElement
253	      const cells = [clock(Date.now()), key, value]
254	      Array.from(line.children).forEach((cell, index) => {
255	        cell.textContent = cells[index] ?? ''
256	      })
257	
258	      log.append(line)
259	      while (log.children.length > MAX_LINES) log.firstElementChild?.remove()
260	
261	      const metrics = metricsAt(tick)
262	      for (const figure of figures) {
263	        const name = figure.dataset.metric
264	        if (name && name in metrics)
265	          figure.textContent = String(metrics[name as keyof typeof metrics])
266	      }
267	    })
268	  }
269	</script>
